@app.post("/users")
def create_user(user: UserSchema):
    if user.email in existing_emails:
        raise HTTPException(
            status_code=409,
            detail={
                "error": {
                    "code": "EMAIL_ALREADY_EXISTS",
                    "message": "A user with this email address already exists.",
                    "field": "email"
                }
            }
        )
    return {"status": "success"}

